const labels=['ข้อมูลเบื้องต้น','ภาพถ่าย','ตรวจสอบ','ผลประเมิน'];const angles=['ด้านหน้า','ด้านหลัง','ด้านซ้าย','ด้านขวา'];const state={step:0,max:0,gender:'male',values:{height:'',weight:'',waist:'',hip:'',chest:''},photos:[null,null,null,null],sample:false,consent:false,busy:false};const surface=document.querySelector('#surface');const escapeText=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function go(n){if(state.busy)return;state.step=n;state.max=Math.max(state.max,n);render();surface.querySelector('h2')?.focus({preventScroll:true});}
function field(key,title,unit,min,max){return `<div class="field"><label for="${key}">${title}${key==='waist'?'<button type="button" class="inline-help" data-help="waist" aria-label="วิธีดูรอบเอวกางเกง">ⓘ</button>':''}</label><div class="input-wrap"><input id="${key}" name="${key}" type="number" inputmode="decimal" step="any" min="${min}" max="${max}" required value="${escapeText(state.values[key])}" autocomplete="off"><span>${unit}</span></div>${key==='waist'?'<p class="hint">รอบเอวกางเกงที่คุณใส่ หน่วยนิ้ว</p>':''}</div>`}
function render(){document.querySelector('#steps').innerHTML=labels.map((l,i)=>`<button class="step ${i===state.step?'active':i<state.step?'complete':''}" ${i>state.max||state.busy?'disabled':''} data-step="${i}" ${i===state.step?'aria-current="step"':''}><b>${i<state.step?'✓':i+1}</b><span>${l}</span></button>`).join('');let body='';if(state.step===0){body=`<h2 tabindex="-1">ข้อมูลเบื้องต้น</h2><p class="sub">เริ่มจากข้อมูลที่คุณทราบ</p><div class="gender" role="group" aria-label="ประเภทสูท"><button data-gender="male" class="${state.gender==='male'?'selected':''}" aria-pressed="${state.gender==='male'}">สูทผู้ชาย</button><button data-gender="female" class="${state.gender==='female'?'selected':''}" aria-pressed="${state.gender==='female'}">สูทผู้หญิง</button></div><form id="basics">${field('height','ส่วนสูง','cm',100,230)}${field('weight','น้ำหนัก','kg',25,250)}${field('waist','รอบเอวกางเกง','นิ้ว',20,70)}${state.gender==='female'?field('chest','รอบอก','นิ้ว',20,70)+field('hip','รอบสะโพก','นิ้ว',20,80):''}<div class="actions"><button class="primary" type="submit">ถัดไป: เตรียมภาพถ่าย <span aria-hidden="true">→</span></button></div></form><p class="form-foot">ข้อมูลอยู่ในหน้านี้เท่านั้น ไม่ต้องสมัครสมาชิก</p>`}else if(state.step===1){body=`<h2 tabindex="-1">ภาพถ่ายของคุณ</h2><p class="sub">เตรียมภาพเต็มตัวทั้ง 4 มุม</p><div class="photos">${angles.map((a,i)=>`<div class="photo-card"><div class="photo-preview">${state.photos[i]?state.photos[i].sample?'<span>ภาพเดโม</span>':`<img src="${state.photos[i].url}" alt="ภาพ${a}">`:'▣'}</div><strong>${a} ${state.photos[i]?'✓':''}</strong><label for="photo${i}">${state.photos[i]?'เปลี่ยนภาพ':'เลือกภาพ'}<input id="photo${i}" type="file" accept="image/jpeg,image/png,image/webp" data-photo="${i}"></label>${state.photos[i]?`<button data-remove="${i}">นำภาพออก</button>`:''}</div>`).join('')}</div><p class="privacy">รองรับ JPG, PNG, WebP ไม่เกิน 10 MB ต่อภาพ<br>เดโมนี้แสดงภาพบนอุปกรณ์ของคุณ ไม่ส่งภาพไปยังเซิร์ฟเวอร์ และไม่ตรวจวิเคราะห์รูปร่าง</p><button class="text-button" data-help="photo">ดูตัวอย่างการเตรียมตัว ↗</button><p class="error" id="error" role="alert"></p><div class="actions"><button class="secondary" data-step="0">ย้อนกลับ</button><button class="primary" id="photos-next">ถัดไป: ตรวจสอบข้อมูล →</button></div>`}else if(state.step===2){body=`<h2 tabindex="-1">ตรวจสอบอีกครั้ง</h2><p class="sub">ข้อมูลถูกต้องแล้ว พร้อมดูผลตัวอย่าง</p><div class="review"><div><span>ประเภทสูท</span><strong>${state.gender==='male'?'สูทผู้ชาย':'สูทผู้หญิง'}</strong></div>${Object.entries(state.values).filter(([k,v])=>v&&(state.gender==='female'||!['chest','hip'].includes(k))).map(([k,v])=>`<div><span>${({height:'ส่วนสูง',weight:'น้ำหนัก',waist:'รอบเอวกางเกง',chest:'รอบอก',hip:'รอบสะโพก'})[k]}</span><strong>${escapeText(v)} ${k==='height'?'cm':k==='weight'?'kg':'นิ้ว'}</strong></div>`).join('')}</div><button class="text-button" data-step="0">แก้ไขข้อมูล ↗</button><div class="mini-photos">${state.photos.map((p,i)=>p?.sample?`<span>${angles[i]}</span>`:`<img src="${p?.url||''}" alt="${angles[i]}">`).join('')}</div><button class="text-button" data-step="1">แก้ไขภาพถ่าย ↗</button><label class="check"><input type="checkbox" id="confirm" ${state.consent?'checked':''}>ฉันเข้าใจว่าผลลัพธ์ในเดโมเป็นข้อมูลตัวอย่าง ไม่ใช่ขนาดสำหรับสั่งตัดจริง</label><p class="error" id="error" role="alert"></p><div class="actions"><button class="secondary" data-step="1">ย้อนกลับ</button><button class="primary" id="result">ดูผลประเมินตัวอย่าง →</button></div>`}else{body=`<div class="success-mark">✓</div><h2 tabindex="-1">สรุปผลตัวอย่างของคุณ</h2><p class="sub">ครบทุกขั้นตอนแล้ว นี่คือตัวอย่างหน้าผลลัพธ์</p><div class="result-card"><small>ตัวอย่างการแสดงผล • ไม่ใช่ผล AI จริง</small><div class="result-size">${state.gender==='male'?'50':'38'} <span>/ Regular</span></div><strong>ขนาดเสื้อสูทตัวอย่าง</strong><p class="result-warning">ตัวเลขนี้คงที่สำหรับสาธิตหน้าจอ ไม่ได้คำนวณจากข้อมูลหรือภาพของคุณ และไม่ควรใช้สั่งตัด</p></div><div class="review"><div><span>ข้อมูลที่กรอก</span><strong>${escapeText(state.values.height)} cm · ${escapeText(state.values.weight)} kg</strong></div><div><span>ภาพที่เตรียม</span><strong>4 มุมครบแล้ว</strong></div></div><p class="privacy">ในการใช้งานจริง ผลประเมินและขั้นตอนสั่งซื้อจะเชื่อมกับระบบของ SUITCUBE</p><div class="actions"><button class="secondary" data-step="2">แก้ไขข้อมูล</button><button class="primary" id="print">พิมพ์สรุปเดโม</button></div><button class="text-button" id="reset">เริ่มใหม่ทั้งหมด ↗</button>`}surface.innerHTML=body;bind();}
function bind(){document.querySelector('#basics')?.addEventListener('input',e=>{if(e.target.name){state.values[e.target.name]=e.target.value;state.max=0;state.consent=false;}});document.querySelector('#basics')?.addEventListener('submit',e=>{e.preventDefault();go(1)});document.querySelectorAll('[data-photo]').forEach(el=>el.addEventListener('change',()=>loadPhoto(Number(el.dataset.photo),el.files[0])));document.querySelector('#photos-next')?.addEventListener('click',()=>{if(state.photos.some(p=>!p))return error('กรุณาเลือกภาพให้ครบทั้ง 4 มุมก่อนดำเนินการต่อ');go(2)});document.querySelector('#confirm')?.addEventListener('change',e=>state.consent=e.target.checked);document.querySelector('#result')?.addEventListener('click',()=>{if(!state.consent)return error('กรุณายืนยันว่าคุณเข้าใจการใช้ข้อมูลตัวอย่าง');state.busy=true;surface.innerHTML='<div class="loading" role="status"><div class="spinner"></div><h2>กำลังเตรียมหน้าผลลัพธ์</h2><p class="sub">แสดงข้อมูลตัวอย่างสำหรับเดโม</p></div>';setTimeout(()=>{state.busy=false;go(3)},1000)});document.querySelector('#print')?.addEventListener('click',()=>window.print());document.querySelector('#reset')?.addEventListener('click',()=>showHelp('reset'));}
function error(t){document.querySelector('#error').textContent=t}
async function loadPhoto(i,file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)return error('เลือกไฟล์ JPG, PNG หรือ WebP ขนาดไม่เกิน 10 MB');const url=URL.createObjectURL(file);const img=new Image();try{await new Promise((ok,no)=>{img.onload=ok;img.onerror=no;img.src=url});if(state.photos[i]?.url)URL.revokeObjectURL(state.photos[i].url);state.photos[i]={url};state.max=1;state.consent=false;render()}catch{URL.revokeObjectURL(url);error('เปิดภาพนี้ไม่ได้ กรุณาลองเลือกภาพอื่น')}}
function sample(){if(state.busy)return;state.values={height:'175',weight:'70',waist:'32',hip:'',chest:''};state.gender='male';state.photos.forEach(p=>{if(p?.url)URL.revokeObjectURL(p.url)});state.photos=angles.map(()=>({sample:true}));state.sample=true;state.consent=false;state.max=1;go(0)}
function reset(){state.photos.forEach(p=>{if(p?.url)URL.revokeObjectURL(p.url)});Object.assign(state,{step:0,max:0,gender:'male',values:{height:'',weight:'',waist:'',hip:'',chest:''},photos:[null,null,null,null],sample:false,consent:false,busy:false});render();document.querySelector('#dialog').close()}
const help={how:['วัดตัวทีละขั้น','<ol><li>กรอกข้อมูลเบื้องต้นและหน่วยให้ถูกต้อง</li><li>เลือกภาพเต็มตัวด้านหน้า หลัง ซ้าย และขวา</li><li>ตรวจสอบข้อมูลและยืนยันการดูผลตัวอย่าง</li><li>ดูหน้าสรุป หรือย้อนกลับแก้ไขข้อมูล</li></ol><p>กด “ลองด้วยข้อมูลตัวอย่าง” เพื่อทดลองได้โดยไม่ต้องใช้ภาพส่วนตัว</p>'],photo:['เตรียมภาพถ่ายอย่างไร','<ol><li>สวมเสื้อยืดและกางเกงที่พอดีตัว ไม่สวมเสื้อคลุม</li><li>ยืนตรง เห็นตั้งแต่ศีรษะถึงเท้า แขนแยกจากลำตัวเล็กน้อย</li><li>ตั้งกล้องตรง ไม่เอียง และใช้พื้นหลังเรียบ</li><li>ถ่ายให้ครบด้านหน้า ด้านหลัง ด้านซ้าย และด้านขวา</li></ol><p>เดโมนี้ตรวจเฉพาะชนิดไฟล์ ขนาด และการเปิดภาพ ยังไม่ตรวจความถูกต้องของท่ายืน</p>'],waist:['รอบเอวกางเกง','<p>ใช้รอบเอวกางเกงที่คุณใส่เป็นหน่วยนิ้ว เช่น 32 นิ้ว โดยตรวจสอบว่าเป็นหน่วยนิ้ว ไม่ใช่รหัสไซซ์ของแบรนด์</p><p>อย่าสลับกับรอบเอวเสื้อสูท หากไม่แน่ใจ ให้สอบถามสไตลิสต์ก่อนใช้ข้อมูลสั่งตัดจริง</p>'],privacy:['ข้อมูลในเดโมนี้','<p>ข้อมูลและภาพที่เลือกเก็บชั่วคราวในหน้านี้ ไม่อัปโหลดไปยังระบบวัดตัว และไม่บันทึกไว้หลังรีเฟรชหรือปิดหน้า</p><p>ผลประเมินเป็นตัวอย่างคงที่ ไม่ได้ผ่านการวิเคราะห์ด้วย AI</p>'],stylist:['ปรึกษาทีม SUITCUBE','<p>หากต้องการสอบถามบริการจริง ติดต่อผ่านเว็บไซต์หลักของ SUITCUBE ได้โดยตรง</p><p><a href="https://www.suitcube.com/" target="_blank" rel="noopener">ไปยังเว็บไซต์ SUITCUBE ↗</a></p><p>เดโมนี้ยังไม่ได้เชื่อมระบบแชทหรือส่งข้อมูลให้ทีมงาน</p>'],reset:['เริ่มใหม่ทั้งหมด?','<p>ข้อมูลและภาพที่เลือกในเดโมจะถูกล้างออกจากหน้านี้</p><button class="secondary" id="confirm-reset">ล้างข้อมูลและเริ่มใหม่</button>']};function showHelp(key){const h=help[key];if(!h)return;document.querySelector('#dialog-content').innerHTML=`<h2>${h[0]}</h2>${h[1]}`;document.querySelector('#dialog').showModal();document.querySelector('#confirm-reset')?.addEventListener('click',reset)}
document.addEventListener('click',e=>{const step=e.target.closest('[data-step]');if(step&&!step.disabled){const n=Number(step.dataset.step);if(n<=state.max)go(n)}const gender=e.target.closest('[data-gender]');if(gender){state.gender=gender.dataset.gender;state.max=0;state.consent=false;render()}const h=e.target.closest('[data-help]');if(h)showHelp(h.dataset.help);const remove=e.target.closest('[data-remove]');if(remove){const i=Number(remove.dataset.remove);if(state.photos[i]?.url)URL.revokeObjectURL(state.photos[i].url);state.photos[i]=null;state.max=1;state.consent=false;render()}});document.querySelector('#sample').addEventListener('click',sample);document.querySelector('#close-dialog').addEventListener('click',()=>document.querySelector('#dialog').close());render();
if(document.modelContext?.registerTool){for(const tool of [{name:'read_fitting_demo_step',description:'Read current demo step and image count, without returning personal measurements or images.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected empty input');return{step:state.step+1,label:labels[state.step],photoCount:state.photos.filter(Boolean).length,isDemo:true}}},{name:'load_fitting_demo_sample',description:'Replace current form and photos with explicit sample demo data, then show the first step.',inputSchema:{type:'object',properties:{confirmReplace:{type:'boolean'}},required:['confirmReplace'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(input?.confirmReplace!==true||Object.keys(input).length!==1)throw Error('confirmReplace must be true');if(state.busy)throw Error('Please wait for current step');sample();return{step:1,sampleLoaded:true}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
